import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9bc4bf);scene.fog=new THREE.FogExp2(0x9bc4bf,.0025);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,900);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
scene.add(new THREE.HemisphereLight(0xc9e6d9,0x354735,2.0));
const sun=new THREE.DirectionalLight(0xffe6bc,3.0);sun.position.set(-80,110,-40);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;scene.add(sun);
const fill=new THREE.DirectionalLight(0x82c9d0,.7);fill.position.set(70,35,100);scene.add(fill);
const clock=new THREE.Clock();const world={seed:812, day:0, weather:0};let started=false,paused=true,lastTime=0,noticeTimer=0,toastTimer=0,combatTimer=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist2=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z),v3=(x,y,z)=>new THREE.Vector3(x,y,z);
const mat=(color,rough=.85)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const mats={bark:mat(0x5b4831),leaf:mat(0x396347),leaf2:mat(0x527b48),leaf3:mat(0x718346),sand:mat(0xdac99b),rock:mat(0x737b68),darkRock:mat(0x485b51),water:mat(0x168c9b,.3)};
function terrainHeight(x,z){const r=Math.hypot(x,z),fade=clamp((205-r)/32,0,1);const hills=(Math.sin(x*.022+1.3)*Math.cos(z*.019)+Math.sin(z*.038+x*.011)*.48+Math.cos((x+z)*.031)*.32);const peak=Math.exp(-((x-35)**2+(z+30)**2)/2200)*36+Math.exp(-((x+75)**2+(z-45)**2)/1400)*21;return Math.max(-1,fade*(4+hills*6+peak));}
function terrainColor(x,z,y){let c;if(y<.3)c=new THREE.Color(0xc9b784);else if(y<5)c=new THREE.Color(0x77905c);else if(y<15)c=new THREE.Color(0x4e754b);else if(y<27)c=new THREE.Color(0x536d50);else c=new THREE.Color(0x8a927c);let shade=.92+Math.sin(x*.11+z*.08)*.045+Math.cos(z*.15)*.025;return c.multiplyScalar(shade);}
// sculpted, walkable island
{
 const n=168,size=450,positions=[],colors=[],indices=[];
 for(let iz=0;iz<=n;iz++)for(let ix=0;ix<=n;ix++){const x=(ix/n-.5)*size,z=(iz/n-.5)*size,y=terrainHeight(x,z);positions.push(x,y,z);const c=terrainColor(x,z,y);colors.push(c.r,c.g,c.b);}
 for(let iz=0;iz<n;iz++)for(let ix=0;ix<n;ix++){const a=iz*(n+1)+ix,b=a+n+1;indices.push(a,b,a+1,b,b+1,a+1)}
 const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();const m=new THREE.MeshStandardMaterial({vertexColors:true,roughness:1});const land=new THREE.Mesh(g,m);land.receiveShadow=true;scene.add(land);
}
// animated ocean surface
const oceanMat=new THREE.ShaderMaterial({transparent:false,uniforms:{uTime:{value:0},uSun:{value:new THREE.Color(0xd1d7ad)}},vertexShader:`uniform float uTime; varying vec3 vPos; varying vec3 vWorld; void main(){vec3 p=position;float w=sin(p.x*.055+uTime*1.1)*.34+cos(p.y*.067-uTime*.82)*.24+sin((p.x+p.y)*.027+uTime*.6)*.28;p.z+=w;vPos=p;vec4 world=modelMatrix*vec4(p.x,p.y,0.0,1.0);vWorld=world.xyz;gl_Position=projectionMatrix*viewMatrix*world;}`,fragmentShader:`uniform float uTime;uniform vec3 uSun;varying vec3 vPos;varying vec3 vWorld;void main(){float bands=sin(vPos.x*.19+uTime*1.6)*sin(vPos.y*.14-uTime*1.1);float fres=pow(1.0-abs(normalize(cameraPosition-vWorld).y),2.0);vec3 deep=vec3(.025,.25,.30),shallow=vec3(.12,.52,.53);vec3 col=mix(deep,shallow,smoothstep(-.8,.8,bands)*.25+.32);col+=uSun*pow(max(0.0,bands),10.0)*.20;col=mix(col,vec3(.35,.68,.64),fres*.25);gl_FragColor=vec4(col,.91);}`});
const ocean=new THREE.Mesh(new THREE.PlaneGeometry(1200,1200,1,1),oceanMat);ocean.rotation.x=-Math.PI/2;ocean.position.y=-.55;scene.add(ocean);
// distant atmospheric island silhouettes and sun glow
const sunDisc=new THREE.Mesh(new THREE.CircleGeometry(13,40),new THREE.MeshBasicMaterial({color:0xffe6ac,transparent:true,opacity:.27,depthWrite:false}));sunDisc.position.set(-95,76,-340);scene.add(sunDisc);sunDisc.lookAt(camera.position);
function makeTree(x,z,scale=1){const group=new THREE.Group();group.position.set(x,terrainHeight(x,z),z);group.scale.setScalar(scale);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.28,.65,7,7),mats.bark);trunk.position.y=3.5;trunk.castShadow=true;group.add(trunk);for(let i=0;i<4;i++){const crown=new THREE.Mesh(new THREE.ConeGeometry(rand(3,4.7),rand(7,10),7),[mats.leaf,mats.leaf2,mats.leaf3][Math.floor(Math.random()*3)]);crown.position.set(rand(-.8,.8),5+i*1.9,rand(-.8,.8));crown.castShadow=true;group.add(crown)}scene.add(group);return group;}
function makePalm(x,z,s=1){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);g.scale.setScalar(s);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.3,.55,8,7),mats.bark);trunk.position.y=4;trunk.rotation.z=.1;trunk.castShadow=true;g.add(trunk);for(let i=0;i<7;i++){const a=i*Math.PI*2/7,leaf=new THREE.Mesh(new THREE.ConeGeometry(.6,6,5),mats.leaf2);leaf.rotation.z=-Math.PI/2+Math.sin(a)*.3;leaf.rotation.y=a;leaf.position.set(Math.cos(a)*2,7+Math.sin(a)*.5,Math.sin(a)*2);leaf.castShadow=true;g.add(leaf)}scene.add(g);return g;}
function makeRock(x,z,s){const o=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),Math.random()<.45?mats.darkRock:mats.rock);o.position.set(x,terrainHeight(x,z)+s*.38,z);o.scale.set(1,rand(.65,1.2),rand(.75,1.25));o.rotation.set(rand(0,.5),rand(0,6),rand(0,.4));o.castShadow=true;o.receiveShadow=true;scene.add(o);return o;}
// vegetation is seeded into the island, leaving paths and a playable shoreline
for(let i=0;i<215;i++){let x=rand(-190,190),z=rand(-190,190),r=Math.hypot(x,z),y=terrainHeight(x,z);if(r<48||r>190||y<3)continue;if(r>145&&Math.random()<.62)makePalm(x,z,rand(.65,1.15));else makeTree(x,z,rand(.7,1.35));}
for(let i=0;i<68;i++){let a=rand(0,Math.PI*2),r=rand(28,192),x=Math.cos(a)*r,z=Math.sin(a)*r;if(terrainHeight(x,z)>0)makeRock(x,z,rand(.6,2.5));}
// tropical undergrowth and shore details
const bushMat=[mat(0x597847),mat(0x718448),mat(0x426b4b)];
for(let i=0;i<190;i++){const x=rand(-180,180),z=rand(-180,180),r=Math.hypot(x,z);if(r<35||r>190||terrainHeight(x,z)<2)continue;const b=new THREE.Mesh(new THREE.IcosahedronGeometry(rand(.45,.95),1),bushMat[i%3]);b.position.set(x,terrainHeight(x,z)+.45,z);b.scale.y=.7;b.castShadow=true;scene.add(b);}
// small distant islets
for(const [x,z,r] of [[-270,-80,31],[250,60,37],[35,270,27],[-190,235,22]]){const island=new THREE.Mesh(new THREE.SphereGeometry(r,16,8),mat(0x526d49));island.scale.y=.2;island.position.set(x,-2,z);island.castShadow=true;scene.add(island);const palm=makePalm(x,z,.8);}
// scattered shoreline foam glints
const foamMat=new THREE.MeshBasicMaterial({color:0xe6eddc,transparent:true,opacity:.36,side:THREE.DoubleSide});
for(let i=0;i<90;i++){const a=i/90*Math.PI*2,r=205+Math.sin(i*2.7)*3,x=Math.cos(a)*r,z=Math.sin(a)*r;const f=new THREE.Mesh(new THREE.PlaneGeometry(rand(2,7),.35),foamMat);f.rotation.x=-Math.PI/2;f.rotation.z=a+Math.PI/2;f.position.set(x,.12,z);scene.add(f);}

const player={pos:v3(0,terrainHeight(0,72)+.12,72),vel:v3(0,0,0),yaw:Math.PI,health:100,stamina:100,xp:0,level:1,berries:0,wood:0,weapon:false,attackCd:0,heavyCd:0,dashCd:0,invuln:0,attackAnim:0,jump:false,speed:0};
const creatureSpecs=[
 {name:'Tyrannosaur',color:0x9b6244,size:1.55,hp:110,dmg:17,speed:2.4,aggressive:true,kind:'rex'},
 {name:'Triceratops',color:0x8d9366,size:1.35,hp:95,dmg:13,speed:1.15,kind:'trike'},
 {name:'Stegosaurus',color:0xb28a55,size:1.3,hp:85,dmg:12,speed:1.3,kind:'stego'},
 {name:'Velociraptor',color:0x56775a,size:.8,hp:48,dmg:11,speed:3.2,aggressive:true,kind:'raptor'},
 {name:'Brontosaurus',color:0x778477,size:2.1,hp:180,dmg:14,speed:.8,kind:'bronto'},
 {name:'Pteranodon',color:0x8f735f,size:.72,hp:32,dmg:8,speed:2.3,kind:'ptero'},
 {name:'Ankylosaurus',color:0x777e58,size:1.12,hp:105,dmg:16,speed:.9,kind:'anky'},
 {name:'Parasaurolophus',color:0x8b8461,size:1.15,hp:75,dmg:6,speed:1.35,kind:'para'},
 {name:'Swamp Crocodile',color:0x4b6850,size:.92,hp:72,dmg:14,speed:1.65,aggressive:true,kind:'croc'}
];
const creatures=[];
function makeCreature(spec,x,z,boss=false){
 const g=new THREE.Group(),scale=spec.size*(boss?1.8:1);g.position.set(x,terrainHeight(x,z)+.1,z);g.scale.setScalar(scale);const skin=mat(spec.color),belly=mat(new THREE.Color(spec.color).multiplyScalar(1.23)),dark=mat(0x342f2a),eye=mat(0xf1d57d,.4);const parts=[],legs=[];
 const sphere=(parent,m,pos,sz,seg=12)=>{const o=new THREE.Mesh(new THREE.SphereGeometry(1,seg,Math.max(7,seg-3)),m);o.position.set(...pos);o.scale.set(...sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;};
 sphere(g,skin,[-.05,1,0],[1.22,.72,1.72]);sphere(g,belly,[.12,.66,.05],[1.02,.37,1.4]);
 if(['rex','raptor','croc'].includes(spec.kind)){
  sphere(g,skin,[1.15,1.2,0],[.73,.63,.77]);sphere(g,skin,[1.65,.96,.04],[.7,.35,.48]);sphere(g,dark,[1.8,.78,.05],[.6,.12,.43]);
  sphere(g,eye,[1.34,1.46,.56],[.105,.12,.07],8);sphere(g,dark,[1.34,1.46,-.56],[.105,.12,.07],8);
  const tail=sphere(g,skin,[-1.42,.96,0],[1.42,.27,.39]);tail.rotation.z=-.1;
  if(spec.kind==='rex'){for(const side of [-1,1]){const arm=sphere(g,skin,[.65,.73,side*.56],[.2,.43,.18]);arm.rotation.z=-.4;}for(let i=0;i<5;i++){const tooth=new THREE.Mesh(new THREE.ConeGeometry(.055,.18,5),mat(0xe9dfbd));tooth.rotation.z=Math.PI;tooth.position.set(1.57+i*.12,.85,0);g.add(tooth)}}
  if(spec.kind==='croc'){for(let i=0;i<5;i++)sphere(g,skin,[-.55+i*.43,1.59,0],[.19,.18,.65]);}
 } else if(spec.kind==='bronto'){
  const neck=sphere(g,skin,[.95,2.1,0],[.35,1.45,.38]);neck.rotation.z=-.28;sphere(g,skin,[1.42,3.2,0],[.48,.38,.42]);sphere(g,dark,[1.62,3.05,.32],[.07,.08,.05],8);sphere(g,skin,[-1.65,.9,0],[1.35,.17,.22]);
 }else if(spec.kind==='trike'){
  sphere(g,skin,[1.08,1.05,0],[.65,.55,.72]);sphere(g,skin,[1.42,.99,.02],[.64,.3,.43]);sphere(g,skin,[.93,1.6,0],[.4,.44,.62]);
  for(const s of [-1,1]){const horn=new THREE.Mesh(new THREE.ConeGeometry(.13,.72,6),mat(0xe4d6ae));horn.rotation.z=-Math.PI/2;horn.position.set(1.17,1.85,s*.38);g.add(horn)}const nose=new THREE.Mesh(new THREE.ConeGeometry(.16,.55,6),mat(0xe4d6ae));nose.rotation.z=-Math.PI/2;nose.position.set(1.74,1.1,0);g.add(nose);
 }else{
  sphere(g,skin,[1.12,1.12,0],[.48,.4,.45]);sphere(g,skin,[1.48,1.06,0],[.43,.25,.32]);sphere(g,eye,[1.23,1.34,.3],[.08,.09,.05],8);sphere(g,skin,[-1.55,.89,0],[1.3,.19,.23]);
  if(spec.kind==='stego')for(let i=0;i<7;i++){const p=new THREE.Mesh(new THREE.ConeGeometry(.27,.75,5),mat(i%2?0xa6603c:0xc07b49));p.position.set(.9-i*.42,1.75,0);g.add(p)}
  if(spec.kind==='anky'){for(let i=0;i<9;i++)sphere(g,belly,[.75-i*.36,1.51,(i%2?1:-1)*.45],[.22,.22,.2],7);sphere(g,skin,[-1.95,.75,0],[.36,.3,.3]);}
  if(spec.kind==='para'){const crest=new THREE.Mesh(new THREE.ConeGeometry(.3,.72,6),skin);crest.rotation.z=-Math.PI/2;crest.position.set(1.25,1.55,0);g.add(crest)}
  if(spec.kind==='ptero'){const wingmat=mat(0xa48669);for(const s of [-1,1]){const wing=new THREE.Mesh(new THREE.ConeGeometry(.12,2.6,5),wingmat);wing.rotation.z=s*.48;wing.rotation.x=s*.38;wing.position.set(-.05,1.5,s*1.35);wing.scale.set(1,1,.48);g.add(wing)}const crest=new THREE.Mesh(new THREE.ConeGeometry(.22,.7,5),skin);crest.rotation.z=-Math.PI/2;crest.position.set(1.35,1.5,0);g.add(crest);}
 }
 for(const x of [-.68,.7])for(const z of [-.9,.9]){const leg=new THREE.Group();leg.position.set(x,.76,z);const l=new THREE.Mesh(new THREE.CylinderGeometry(.16,.22,.82,7),skin);l.position.y=-.33;l.castShadow=true;leg.add(l);const foot=sphere(leg,skin,[.17,-.72,.05],[.38,.14,.29],8);g.add(leg);legs.push(leg)}
 scene.add(g);
 const hpmax=spec.hp*(boss?3:1),enemy={spec,group:g,hp:hpmax,maxHp:hpmax,boss,alive:true,home:v3(x,0,z),target:v3(x,0,z),yaw:rand(0,Math.PI*2),phase:rand(0,6),attack:0,notice:false,legs,vel:0};creatures.push(enemy);return enemy;
}
function addWildlife(){const positions=[[-18,38,1],[29,5,0],[61,64,2],[-61,48,3],[74,-35,4],[-82,-43,5],[17,-72,6],[91,82,7],[-102,-18,8],[110,22,0],[-38,-112,2],[48,115,3],[135,-80,1],[-142,83,4]];for(const [x,z,id] of positions){const spec=creatureSpecs[id];makeCreature(spec,x,z)}
 // the remote rainforest guardian sleeps deep in the island
 makeCreature({name:'Ancient Titan',color:0x4b5943,size:2.5,hp:500,dmg:26,speed:1.3,aggressive:true,kind:'rex'},-138,-130,true);
}
function makePlayer(){const root=new THREE.Group();const skin=mat(0xbd8b67),shirt=mat(0x9b6847),pants=mat(0x394741),wrap=mat(0xd0b47f),hair=mat(0x332c25);const mk=(geo,m,p,s)=>{const o=new THREE.Mesh(geo,m);o.position.set(...p);if(s)o.scale.set(...s);o.castShadow=true;o.receiveShadow=true;root.add(o);return o};
 mk(new THREE.CapsuleGeometry(.36,.86,4,8),shirt,[0,1.12,0]);mk(new THREE.SphereGeometry(.29,12,10),skin,[0,1.98,0],[.84,1, .9]);mk(new THREE.SphereGeometry(.3,10,7),hair,[0,2.14,-.035],[1.02,.62,1]);mk(new THREE.BoxGeometry(.52,.12,.45),wrap,[0,1.5,0]);
 const arms=[],legs=[];for(const s of [-1,1]){const arm=new THREE.Group();arm.position.set(s*.43,1.55,0);const a=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.48,3,7),skin);a.position.y=-.32;a.castShadow=true;arm.add(a);const hand=new THREE.Mesh(new THREE.SphereGeometry(.13,8,7),skin);hand.position.y=-.65;arm.add(hand);root.add(arm);arms.push(arm);const leg=new THREE.Group();leg.position.set(s*.17,.78,0);const l=new THREE.Mesh(new THREE.CapsuleGeometry(.15,.55,3,7),pants);l.position.y=-.35;l.castShadow=true;leg.add(l);root.add(leg);legs.push(leg)}
 const pack=new THREE.Mesh(new THREE.BoxGeometry(.5,.58,.25),mat(0x6b5539));pack.position.set(0,1.35,-.3);pack.castShadow=true;root.add(pack);scene.add(root);player.root=root;player.arms=arms;player.legs=legs;player.weaponMesh=null;}
makePlayer();addWildlife();
const pickups=[];
function makePickup(x,z,type){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z)+.8,z);const orb=new THREE.Mesh(new THREE.IcosahedronGeometry(.22,1),type==='berry'?mat(0xd36f66):mat(0xceb77e));g.add(orb);const glow=new THREE.PointLight(type==='berry'?0xf07563:0xffdb8b,.65,3);g.add(glow);scene.add(g);pickups.push({group:g,type,phase:rand(0,7),taken:false});}
for(let i=0;i<35;i++){let x=rand(-160,160),z=rand(-160,160);if(Math.hypot(x,z)>185||terrainHeight(x,z)<1)continue;makePickup(x,z,Math.random()<.66?'berry':'wood')}
const slashMat=new THREE.MeshBasicMaterial({color:0xe9d891,transparent:true,opacity:.75,side:THREE.DoubleSide,depthWrite:false});const slash=new THREE.Mesh(new THREE.TorusGeometry(1.12,.045,5,32,Math.PI*1.18),slashMat);slash.rotation.x=Math.PI/2;slash.visible=false;scene.add(slash);

const keys={},joy={x:0,y:0,active:false},cameraOrbit={yaw:0,pitch:.3,distance:11.5},stats={travel:0,kills:0,damage:0};let prevPos=player.pos.clone(),bossRef=null,activeBoss=false,quest=0,lastBanner=0;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function announce(text){const el=$('#notice');el.textContent=text;el.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function setQuest(n){quest=n;const titles=['A NEW BEGINNING','A DANGEROUS NEIGHBOR','THE DEEP GREEN'];const texts=['Explore the coast. The island is watching.','Something hungry is following your trail.','A great shadow stirs in the old forest.'];const status=['WALK 120M TO THE FOREST','DEFEAT A PREDATOR','FIND THE ANCIENT TITAN'];$('#quest-title').textContent=titles[n];$('#quest-text').textContent=texts[n];$('#quest-status').textContent=status[n];$('#progress-label').textContent=`0${n+1} / 03`;$('#quest-value').textContent=n===0?`${Math.floor(stats.travel)} / 120m`:n===1?`${stats.kills} / 1`:'UNKNOWN';$('#quest-fill').style.width=n===0?`${clamp(stats.travel/120*100,0,100)}%`:n===1?`${stats.kills?100:0}%`:'0%';}
function showThreat(enemy){if(enemy.boss){$('#boss-bar').classList.add('show');$('#boss-name').textContent=enemy.spec.name.toUpperCase();activeBoss=true;}else if(Date.now()-lastBanner>6500){$('#combat-banner').classList.add('show');$('#banner-title').textContent=`${enemy.spec.name.toUpperCase()} NEARBY`;lastBanner=Date.now();setTimeout(()=>$('#combat-banner').classList.remove('show'),2200)}}
function enemyDied(e){e.alive=false;scene.remove(e.group);stats.kills++;player.xp+=e.boss?150:35;player.wood+=e.boss?5:1;if(e.boss){$('#boss-bar').classList.remove('show');announce('THE ANCIENT TITAN HAS FALLEN');toast('ANCIENT TITAN DEFEATED · +150 XP')}else toast(`${e.spec.name.toUpperCase()} DEFEATED · +35 XP`);if(quest===1&&stats.kills>=1){setQuest(2);announce('A DISTANT ROAR SHAKES THE FOREST')}checkLevel();}
function checkLevel(){const needed=player.level*120;if(player.xp>=needed){player.xp-=needed;player.level++;player.health=Math.min(100,player.health+18);toast(`LEVEL UP · SURVIVOR LV ${String(player.level).padStart(2,'0')}`)}}
function doAttack(heavy=false){if(!started||paused||player.health<=0)return;const now=performance.now();if(heavy?player.heavyCd>0:player.attackCd>0)return;if(heavy&&player.stamina<22)return;if(heavy){player.heavyCd=.95;player.stamina-=22;player.attackAnim=.48}else{player.attackCd=.36;player.attackAnim=.3}slash.visible=true;slash.scale.setScalar(heavy?1.38:.95);slash.material=slashMat;slash.position.set(player.pos.x,player.pos.y+1.15,player.pos.z);slash.rotation.y=player.yaw;setTimeout(()=>slash.visible=false,170);let target=null,best=heavy?4.7:3.3;for(const e of creatures){if(!e.alive)continue;const d=dist2(player.pos,e.group.position);if(d<best){const toward=v3(e.group.position.x-player.pos.x,0,e.group.position.z-player.pos.z).normalize();const facing=v3(Math.sin(player.yaw),0,Math.cos(player.yaw));if(toward.dot(facing)>.05||d<1.6){target=e;best=d}}}if(target){const dmg=(heavy?38:22)*(player.weapon?1.38:1)*(target.boss?.8:1);target.hp-=dmg;player.xp+=heavy?3:2;target.group.position.x+=Math.sin(player.yaw)*.65;target.group.position.z+=Math.cos(player.yaw)*.65;toast(`${target.spec.name.toUpperCase()}  −${Math.round(dmg)} HP`);if(target.hp<=0)enemyDied(target);else showThreat(target);updateBossUI();}else if(Math.random()<.22)toast('TOO FAR — MOVE CLOSER');}
function dash(){if(!started||paused||player.dashCd>0||player.stamina<18)return;player.dashCd=1.15;player.stamina-=18;const d=moveDirection();if(d.lengthSq()<.1){d.set(Math.sin(player.yaw),0,Math.cos(player.yaw))}player.pos.addScaledVector(d,3.8);player.invuln=.48;player.root.position.copy(player.pos);toast('DODGE');}
