const toastEl=$('#toast'),noticeEl=$('#notice');function toast(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>toastEl.classList.remove('show'),2300)}function notice(text){noticeEl.textContent=text;noticeEl.classList.add('show');clearTimeout(notice._t);notice._t=setTimeout(()=>noticeEl.classList.remove('show'),1900)}
function setModal(id,show){$(id).classList.toggle('hidden',!show);paused=show;}
$('#start-game').addEventListener('click',()=>{$('#overlay').classList.remove('show');started=true;paused=false;toast('Stay close to the coast. Gather what you can.');});
$('#pause-open').addEventListener('click',()=>setModal('#pause-modal',true));$('#map-open').addEventListener('click',()=>{drawMap();setModal('#map-modal',true)});$('#inventory-open').addEventListener('click',()=>{refreshInventory();setModal('#inventory-modal',true)});
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>{b.closest('.modal').classList.add('hidden');paused=false}));
document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m){m.classList.add('hidden');paused=false}}));
function resetGame(){state.health=100;state.stamina=100;state.berries=0;state.wood=0;state.xp=0;state.level=1;state.distance=0;state.quest=0;state.kills=0;state.hasSpear=false;player.position.set(0,terrainHeight(0,0),0);alpha.hp=alpha.maxHp;alpha.group.visible=false;for(const c of creatures){if(c!==alpha){c.alive=true;c.hp=c.maxHp;c.group.visible=true;c.x=c.homeX;c.z=c.homeZ;c.group.position.set(c.x,terrainHeight(c.x,c.z),c.z)}}for(const p of pickups){p.active=true;p.group.visible=true}refreshInventory();toast('A new life begins.');}
$('#restart-game').addEventListener('click',()=>{resetGame();$('#pause-modal').classList.add('hidden');paused=false});$('#craft-spear').addEventListener('click',()=>{if(state.hasSpear){toast('Your field spear is ready.');return}if(state.wood<3){toast('You need 3 driftwood to craft a spear.');return}state.wood-=3;state.hasSpear=true;spear.visible=true;toast('Field spear crafted — longer reach!');refreshInventory()});
function refreshInventory(){$('#berry-count').textContent=state.berries;$('#wood-count').textContent=state.wood;$('#inv-berries').textContent=state.berries;$('#inv-wood').textContent=state.wood;$('#inv-level').textContent=String(state.level).padStart(2,'0');$('#craft-cost').textContent=state.hasSpear?'CRAFTED':'3 WOOD';}
function addXP(n){state.xp+=n;if(state.xp>=100){state.xp-=100;state.level++;state.health=Math.min(100,state.health+15);toast(`LEVEL UP · SURVIVOR ${String(state.level).padStart(2,'0')}`)}}
function updateQuest(){const titles=['A NEW BEGINNING','A LIGHT IN THE WILD','TEETH IN THE DARK'],texts=['Explore the coast. The island is watching.','Gather island fruit and driftwood to prepare.','The alpha has found you. Stand your ground.'];const status=['WALK 120M TO THE FOREST','GATHER 3 FRUIT + 3 WOOD','DEFEAT THE ALPHA TYRANNOSAUR'];const values=[`${Math.min(120,Math.floor(state.distance))} / 120m`,`${Math.min(3,state.berries)} / 3 fruit · ${Math.min(3,state.wood)} / 3 wood`,alpha.hp<=0?'COMPLETE':'ALPHA ENCOUNTER'];let progress=state.quest===0?Math.min(1,state.distance/120):state.quest===1?Math.min(1,Math.min(state.berries,state.wood)/3):alpha.hp<=0?1:1-alpha.hp/alpha.maxHp;$('#quest-title').textContent=titles[state.quest];$('#quest-text').textContent=texts[state.quest];$('#quest-status').textContent=status[state.quest];$('#quest-value').textContent=values[state.quest];$('#progress-label').textContent=`0${state.quest+1} / 03`;$('#quest-fill').style.width=`${Math.round(progress*100)}%`;if(state.quest===0&&state.distance>=120){state.quest=1;toast('New field note: gather supplies.');}if(state.quest===1&&state.berries>=3&&state.wood>=3){state.quest=2;alpha.group.visible=true;toast('A distant roar rolls across the island…');}}
function drawMap(){const c=$('#map-canvas'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#153c3a';ctx.fillRect(0,0,w,h);ctx.fillStyle='#829166';ctx.beginPath();ctx.ellipse(w/2,h/2,w*.39,h*.41,-.22,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d4c593';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(w/2,h/2,w*.38,h*.4,-.22,0,Math.PI*2);ctx.stroke();ctx.fillStyle='rgba(62,95,67,.7)';for(let i=0;i<80;i++){const a=i*2.399,r=Math.sqrt(i/80)*.34;ctx.beginPath();ctx.arc(w*(.5+Math.cos(a)*r),h*(.5+Math.sin(a)*r),2+(i%3),0,Math.PI*2);ctx.fill()}const px=w/2+player.position.x*.85,pz=h/2+player.position.z*.75;ctx.fillStyle='#f0da8b';ctx.beginPath();ctx.arc(px,pz,6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff4c2';ctx.stroke();for(const c of creatures)if(c.alive&&dist2(c,player.position)<130){ctx.fillStyle=c.kind==='alpha'?'#ff5a47':'#db9565';ctx.fillRect(w/2+c.x*.85-3,h/2+c.z*.75-3,6,6)}}
function attack(power=1){if(paused||!started||state.stamina<(power===2?18:8))return;state.stamina-=power===2?18:8;state.attack=.32;state.heavy=power===2?.5:0;attacking=true;const reach=(state.hasSpear?4.8:3.1)*(power===2?1.35:1);let hit=false;for(const c of creatures){if(!c.alive||!c.group.visible)continue;const d=dist2(c,player.position);const toward=Math.atan2(c.x-player.position.x,c.z-player.position.z);if(d<reach&&Math.abs(Math.atan2(Math.sin(toward-yaw),Math.cos(toward-yaw)))<1.1){c.hp-=power===2?38:state.hasSpear?30:18;hit=true;c.cooldown=Math.min(c.cooldown,.4);if(c.hp<=0){c.alive=false;c.group.visible=false;state.kills++;addXP(c.kind==='alpha'?70:20);if(c.kind==='alpha'){toast('The alpha falls. The island remembers.');}else toast('Predator down · +20 XP');}}}if(hit){state.stamina=Math.min(100,state.stamina+3);notice(power===2?'HEAVY STRIKE':'HIT');}else notice(power===2?'SWING':'MISS')}
function dash(){if(paused||!started||state.stamina<22)return;state.stamina-=22;state.dash=.24;notice('DASH')}
function jump(){if(!paused&&started&&player.position.y<=terrainHeight(player.position.x,player.position.z)+.03)state.jump=5.2}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){const open=document.querySelector('.modal:not(.hidden)');if(open){open.classList.add('hidden');paused=false}else if(started)setModal('#pause-modal',true)}if(e.code==='KeyJ')attack(1);if(e.code==='KeyK')attack(2);if(e.code==='KeyL')dash();if(e.code==='Space')jump();if(e.code==='KeyM'){drawMap();setModal('#map-modal',true)}if(e.code==='KeyI'){refreshInventory();setModal('#inventory-modal',true)}});
window.addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointerdown',e=>{mouseDown=true;lastPointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(mouseDown){yaw-=(e.clientX-lastPointer.x)*.004;pitch=clamp(pitch+(e.clientY-lastPointer.y)*.003,-.05,.72);lastPointer={x:e.clientX,y:e.clientY}}});canvas.addEventListener('pointerup',()=>mouseDown=false);canvas.addEventListener('pointercancel',()=>mouseDown=false);canvas.addEventListener('click',()=>{if(started&&!paused)attack(1)});
let joyPointer=null;const joystick=$('#joystick'),knob=$('#joy-knob');joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);updateJoy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)updateJoy(e)});function updateJoy(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.min(38,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);moveX=Math.cos(a)*len/38;moveZ=Math.sin(a)*len/38;knob.style.transform=`translate(${moveX*30}px,${moveZ*30}px)`}function endJoy(e){if(e.pointerId===joyPointer){joyPointer=null;moveX=moveZ=0;knob.style.transform=''}}joystick.addEventListener('pointerup',endJoy);joystick.addEventListener('pointercancel',endJoy);
document.querySelectorAll('[data-action]').forEach(b=>{const act=()=>({jump,dash:()=>dash(),heavy:()=>attack(2),attack:()=>attack(1)}[b.dataset.action])?.();b.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();act()})});

